<?php
namespace Avanik;
defined('ABSPATH') || exit;

final class  {
    private const OPTION='avanik_sla_drift_guard_release_decision_audit_verification';
    private const CAPABILITY='manage_options';
    public static function register(): void { add_options_page('SLA Drift Guard Release Decision Audit Verification','SLA Drift Guard Release Decision Audit Verification',self::CAPABILITY,'avanik-sla-drift-guard-release-decision-audit-verification',[self::class,'render']); }
    public static function evaluate(): array {
        $a=get_option('avanik_sla_drift_guard_release_decision_audit',[]); $a=is_array($a)?$a:[];
        $valid=($a['audit_status']??'')==='verified' && ($a['source_verification']??'')==='verified' && ($a['decision_status']??'')==='eligible_for_review_decision' && ($a['decision']??'')==='pending_review' && ($a['guard_release']??true)===false && ($a['execution_allowed']??true)===false;
        $result=['verification_status'=>$valid?'verified':'failed','audit_status'=>(string)($a['audit_status']??'unknown'),'source_verification'=>(string)($a['source_verification']??'unknown'),'decision_status'=>(string)($a['decision_status']??'unknown'),'decision'=>(string)($a['decision']??'unknown'),'guard_release'=>false,'execution_allowed'=>false,'reason'=>$valid?'decision_audit_snapshot_is_consistent_and_execution_remains_locked':'decision_audit_snapshot_is_invalid','verified_at'=>time()];
        update_option(self::OPTION,$result,false); return $result;
    }
    public static function render(): void { if(!current_user_can(self::CAPABILITY)) return; $s=self::evaluate(); echo '<div class="wrap"><h1>SLA Drift Guard Release Decision Audit Verification</h1><p>Phase 172 verifies the Phase 171 decision-audit snapshot without changing the pending decision or execution guard.</p><table class="widefat striped"><tbody>'; foreach(['Verification status'=>strtoupper($s['verification_status']),'Audit status'=>strtoupper($s['audit_status']),'Source verification'=>strtoupper($s['source_verification']),'Decision status'=>strtoupper(str_replace('_',' ',$s['decision_status'])),'Decision'=>strtoupper(str_replace('_',' ',$s['decision'])),'Guard release'=>$s['guard_release']?'YES':'NO','Execution allowed'=>$s['execution_allowed']?'YES':'NO','Reason'=>str_replace('_',' ',$s['reason']),'Verified at'=>wp_date('Y-m-d H:i:s',$s['verified_at'])] as $k=>$v) echo '<tr><th>'.esc_html($k).'</th><td>'.esc_html((string)$v).'</td></tr>'; echo '</tbody></table></div>'; }
}
